const nav=[{label:'Home',to:'/'},{label:'Demon List',to:'/list'},{label:'Unverified List',to:'/unverified'},{label:'Submit Level',to:'/submit-level'},{label:'Submit Record',to:'/submit'},{label:'Records',to:'/records'},{label:'Points',to:'/players'},{label:'Rules',to:'/rules'},{label:'About',to:'/about'}];

function UnverifiedAdminPanel({session,isAdmin,setNotice}:{session:Session|null;isAdmin:boolean;setNotice:(s:string)=>void}){
 const [rows,setRows]=useState<any[]>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState('');
 async function load(){if(!supabase||!session||!isAdmin){setLoading(false);return}setLoading(true);const {data,error}=await supabase.from('unverified_levels').select('id,name,gd_level_id,creator,progress_percent,evidence_url,notes,submitter_id,created_at,admin_hidden').order('created_at',{ascending:false}).limit(500);if(error)setNotice(error.message);setRows(data||[]);setLoading(false)}
 useEffect(()=>{void load()},[session,isAdmin]);
 async function toggle(row:any){if(!supabase)return;setBusy(row.id);const {error}=await supabase.from('unverified_levels').update({admin_hidden:!row.admin_hidden}).eq('id',row.id);setBusy('');if(error)setNotice(error.message);else{setNotice(row.admin_hidden?'Unverified entry restored.':'Unverified entry hidden from the public list.');await load()}}
 async function remove(row:any){if(!supabase||!window.confirm('Permanently delete the unverified entry for "'+row.name+'"? This cannot be undone.'))return;setBusy(row.id);const {error}=await supabase.from('unverified_levels').delete().eq('id',row.id);setBusy('');if(error)setNotice(error.message);else{setNotice('Unverified entry deleted.');await load()}}
 return <section className="admin-unverified-panel"><div className="section-heading"><div><h2>UNVERIFIED LIST MANAGEMENT</h2><p>Hide, restore, or permanently delete community progress entries. No points are awarded.</p></div><button className="button button-secondary" onClick={()=>void load()}>Refresh</button></div>{loading?<div className="table-state"><div className="spinner"/> Loading unverified entries…</div>:!rows.length?<div className="empty-state"><p>No unverified entries have been submitted yet.</p></div>:rows.map(row=><article className={'review-card admin-unverified-card '+(row.admin_hidden?'is-hidden':'')} key={row.id}><div className="review-body"><h3>{row.name} <small>{row.gd_level_id?'· GD ID '+row.gd_level_id:''}</small></h3><p>Creator: {row.creator} · Best progress: {row.progress_percent}% · {row.admin_hidden?'Hidden':'Public'}</p><p>Submitted {new Date(row.created_at).toLocaleDateString()} · Submitter ID: {row.submitter_id}</p>{row.notes&&<p>{row.notes}</p>}<div className="review-actions"><a href={row.evidence_url} target="_blank" rel="noreferrer">View evidence ↗</a><button disabled={busy===row.id} onClick={()=>void toggle(row)}>{row.admin_hidden?'Restore to public list':'Hide from public list'}</button><button disabled={busy===row.id} onClick={()=>void remove(row)}>Delete permanently</button></div></div></article>)}</section>
}

export default function App(){
 const [session,setSession]=useState<Session|null>(null),[profileName,setProfileName]=useState(''),[levels,setLevels]=useState<Level[]>([]),[stats,setStats]=useState({levels:0,records:0,players:0}),[loading,setLoading]=useState(true),[search,setSearch]=useState(''),[mobileOpen,setMobileOpen]=useState(false),[authOpen,setAuthOpen]=useState(false),[notice,setNotice]=useState(''),[isStaff,setIsStaff]=useState(false),[isAdmin,setIsAdmin]=useState(false); const location=useLocation();
 useEffect(()=>{let alive=true;const local=window.localStorage.getItem('tgh-theme')||'dark';if(!session){if(local==='light'||local==='dark')document.documentElement.dataset.theme=local;else document.documentElement.removeAttribute('data-theme');return()=>{alive=false}}if(!supabase)return()=>{alive=false};supabase.from('profiles').select('theme').eq('id',session.user.id).maybeSingle().then(({data})=>{if(!alive)return;const value=data?.theme||local;if(value==='light'||value==='dark')document.documentElement.dataset.theme=value;else document.documentElement.removeAttribute('data-theme');window.localStorage.setItem('tgh-theme',value)});return()=>{alive=false}},[session]);
 useEffect(()=>{if(!supabase){setLoading(false);return} supabase.auth.getSession().then(({data})=>setSession(data.session));const {data:listener}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>listener.subscription.unsubscribe()},[]);
 useEffect(()=>{let alive=true;if(!supabase||!session){setIsStaff(false);setIsAdmin(false);return}supabase.from('user_roles').select('role,permissions,banned_at').eq('user_id',session.user.id).maybeSingle().then(({data})=>{if(alive){setIsAdmin(Boolean(data&&data.banned_at==null&&data.role==='admin'));setIsStaff(Boolean(data&&data.banned_at==null&&(data.role==='admin'||data.permissions?.['submissions.review']===true||data.permissions?.['levels.manage']===true)))}});return()=>{alive=false}},[session]);
 useEffect(()=>{let alive=true;async function load(){if(!supabase){setLoading(false);return}setLoading(true);const [lr,sr]=await Promise.all([supabase.from('levels').select('id,sort_order,name,gd_level_id,creator,verifier,status,youtube_url,thumbnail_url,description,minimum_record_percent,points,length',{count:'exact'}).eq('status','published').eq('admin_hidden',false).order('sort_order').range(0,149),supabase.rpc('wcl_public_stats')]);if(!alive)return;if(lr.data)setLevels(lr.data.map((l:any)=>({id:l.id,rank:l.sort_order,name:l.name,level_id:l.gd_level_id||'—',creators:l.creator?[l.creator]:[],verifier:l.verifier||null,status:l.status,video_url:l.youtube_url||null,thumbnail_url:l.thumbnail_url||null,description:l.description||null,minimum_record_percent:l.minimum_record_percent??100,points:l.points??0,length:l.length||'Unrated'})) as Level[]);const statsRow=Array.isArray(sr.data)?sr.data[0]:sr.data;setStats({levels:statsRow?.level_count??lr.count??lr.data?.length??0,records:statsRow?.completion_count??0,players:statsRow?.player_count??0});setLoading(false)}load();return()=>{alive=false}},[session]);
 useEffect(()=>{setMobileOpen(false);setNotice('')},[location.pathname]);useEffect(()=>{if(!notice)return;const id=window.setTimeout(()=>setNotice(''),4200);return()=>window.clearTimeout(id)},[notice]);const filtered=useMemo(()=>levels.filter(l=>[l.name,l.level_id,l.verifier??'',...l.creators].join(' ').toLowerCase().includes(search.toLowerCase())),[levels,search]);
 return <div className="app-shell"><div className="topline"><span><i className="live-dot"/> COMMUNITY-POWERED DEMON LIST</span><span className="topline-right">BUILT BY PLAYERS, FOR PLAYERS <Zap size={12}/></span></div><header className="header wrap"><Link to="/" className="brand"><span className="brand-mark"><Gamepad2 size={25}/><i/></span><span className="brand-copy"><strong>THE GD HUB</strong><small>YOUR NEXT IMPOSSIBLE</small></span><span className="brand-tag">TGH</span></Link><nav className={mobileOpen?'nav nav-open':'nav'}>{nav.map(n=><Link key={n.to} className={location.pathname===n.to?'nav-link active':'nav-link'} to={n.to}>{n.label}</Link>)}{isStaff&&<Link className={location.pathname==='/staff'?'nav-link active':'nav-link'} to='/staff'>Staff review</Link>}{isAdmin&&<Link className={location.pathname==='/admin'?'nav-link active':'nav-link'} to='/admin'>Admin panel</Link>}{session?<button className="account-button" onClick={()=>window.location.hash='#/profile'}><UserRound size={16}/>{profileName||session.user.email?.split('@')[0]||'Account'}</button>:<button className="login-button" onClick={()=>setAuthOpen(true)}><LogIn size={16}/> Log in <ArrowRight size={14}/></button>}</nav><button className="mobile-toggle" aria-label="Toggle navigation" onClick={()=>setMobileOpen(!mobileOpen)}>{mobileOpen?<X/>:<Menu/>}</button></header>{notice&&<div className="notice wrap">{notice}</div>}
 <Routes><Route path="/" element={<Home levels={filtered} stats={stats} loading={loading} search={search} setSearch={setSearch} configured={supabaseConfigured}/>}/><Route path="/list" element={<ListPage levels={filtered} loading={loading} search={search} setSearch={setSearch} configured={supabaseConfigured}/>}/><Route path="/unverified" element={<UnverifiedListPage configured={supabaseConfigured} session={session} onLogin={()=>setAuthOpen(true)} setNotice={setNotice}/>}/><Route path="/submit-unverified" element={<SubmitUnverifiedPage session={session} onLogin={()=>setAuthOpen(true)} setNotice={setNotice}/>}/><Route path="/level/:id" element={<LevelPage levels={levels} session={session} onLogin={()=>setAuthOpen(true)} setNotice={setNotice}/>}/><Route path="/submit" element={<SubmitPage levels={levels} session={session} onLogin={()=>setAuthOpen(true)} setNotice={setNotice}/>}/><Route path="/submit-level" element={<SubmitLevelPage session={session} onLogin={()=>setAuthOpen(true)} setNotice={setNotice}/>}/><Route path="/players" element={<PlayersPage configured={supabaseConfigured}/>}/><Route path="/player/:id" element={<PlayerPage configured={supabaseConfigured}/>}/><Route path="/staff" element={<StaffPage session={session} isStaff={isStaff} setNotice={setNotice} onLogin={()=>setAuthOpen(true)}/>}/><Route path="/admin" element={<AdminPage session={session} isAdmin={isAdmin} setNotice={setNotice} onLogin={()=>setAuthOpen(true)}/>}/><Route path="/records" element={<RecordsPage configured={supabaseConfigured}/>}/><Route path="/rules" element={<InfoPage title="Community rules" kicker="THE STANDARD" icon={<ShieldCheck/>} intro="The GD Hub's policies are being established by its owner and community staff." items={[['List eligibility','Placeholder — ranking criteria will be published after community review.'],['Evidence requirements','Placeholder — proof and video standards are not finalized.'],['Review process','Submissions are reviewed by authorized staff; a video is not automatically accepted.'],['Appeals & conduct','Placeholder — appeal timelines and consequences will be defined by the owner.']]}/>}/><Route path="/about" element={<InfoPage title="A hub for the hardest" kicker="ABOUT TGH" icon={<Gamepad2/>} intro="The GD Hub is a community-maintained place to track challenging Geometry Dash levels and the players who conquer them." items={[['Independent by design','TGH has its own rankings, governance, and review process.'],['Community maintained','Players can submit completion evidence for staff review.'],['Built to earn trust','Permissions are enforced in the database, and moderation decisions are designed to be auditable.']]}/>}/><Route path="/profile" element={<ProfilePage session={session} setProfileName={setProfileName} setNotice={setNotice} onLogin={()=>setAuthOpen(true)}/>}/><Route path="*" element={<InfoPage title="Page not found" kicker="404 / OFF THE GRID" icon={<CircleHelp/>} intro="Looks like this route hasn't been ranked." items={[]}/>}/></Routes>
 <footer className="footer"><div className="wrap footer-inner"><Link to="/" className="brand footer-brand"><span className="brand-mark"><Gamepad2 size={21}/><i/></span><span className="brand-copy"><strong>THE GD HUB</strong><small>COMMUNITY-POWERED</small></span></Link><span>Independent community project · Not affiliated with RobTop Games</span><div className="footer-links"><Link to="/rules">Rules</Link><Link to="/about">About</Link><a href="https://github.com/SolanceGMD/The-GD-Hub" target="_blank" rel="noreferrer">GitHub <ExternalLink size={12}/></a></div></div></footer>{authOpen&&<AuthModal onClose={()=>setAuthOpen(false)} onNotice={setNotice}/>}</div>
}
function Home({levels,stats,loading,search,setSearch,configured}:{levels:Level[];stats:{levels:number;records:number;players:number};loading:boolean;search:string;setSearch:(s:string)=>void;configured:boolean}){return <main className="pointer-home"><section className="pointer-intro"><h1>The GD Hub Demonlist</h1><p>The community-powered ranking of Geometry Dash's hardest levels.</p><p>Browse ranked levels, check player records, and submit your own completions for review.</p><div className="pointer-stats"><span><strong>{loading?'—':stats.levels.toLocaleString()}</strong> ranked levels</span><span><strong>{loading?'—':stats.records.toLocaleString()}</strong> accepted records</span><span><strong>{loading?'—':stats.players.toLocaleString()}</strong> players</span></div></section><section className="pointer-list-section"><div className="pointer-list-heading"><div><h2>Main List</h2><p>The hardest levels currently ranked by The GD Hub.</p></div><Link to="/submit" className="pointer-submit">Submit a record →</Link></div><div className="list-toolbar pointer-toolbar"><div className="searchbox"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Filter by level name, creator, verifier, or ID…" aria-label="Search levels"/></div><Link to="/list" className="filter-button">Full list →</Link></div><LevelTable levels={levels} loading={loading} configured={configured}/></section><section className="pointer-list-section unverified-promo"><div className="pointer-list-heading"><div><h2>Unverified List</h2><p>Show your hardest unverified levels and best progress. 21%+ with evidence — no verification and no points.</p></div><Link to="/unverified" className="pointer-submit">Explore unverified levels →</Link></div><div className="unverified-promo-actions"><span><Zap size={16}/> Progress tracking for impossible levels</span><Link to="/submit-unverified" className="filter-button">Submit a level + run →</Link></div></section><section className="pointer-help"><h2>How The GD Hub works</h2><p>Levels are ranked by the community. Players can submit video evidence of their completions, which is reviewed before a record is accepted.</p><div><Link to="/rules">Read the rules</Link><Link to="/records">Accepted records</Link><Link to="/about">About the project</Link></div></section></main>}
function LevelTable({levels,loading,configured}:{levels:Level[];loading:boolean;configured:boolean}){if(loading)return <div className="table-state"><div className="spinner"/> Loading the list...</div>;if(!configured)return <div className="empty-state"><div className="empty-icon"><Zap size={23}/></div><h3>THE LIST IS POWERING UP</h3><p>Connect Supabase to load real rankings. No levels or records have been fabricated.</p><span className="setup-pill"><i className="live-dot"/> DATABASE NOT CONNECTED</span></div>;if(!levels.length)return <div className="empty-state"><div className="empty-icon"><Search size={23}/></div><h3>NO LEVELS ON THE RADAR</h3><p>No ranked levels found. Check back as the community builds the list.</p></div>;return <div className="level-table"><div className="table-head"><span>RANK</span><span>LEVEL / CREATOR</span><span>POINTS</span><span>VERIFIER</span><span/></div>{levels.map(l=><div className="level-row" key={l.id}><span className="rank">#{String(l.rank).padStart(2,'0')}</span><Link className="level-name" to={'/level/'+l.id}>{l.thumbnail_url&&<img className="level-thumb" src={l.thumbnail_url} alt={`${l.name} thumbnail`} loading="lazy" onError={e=>{e.currentTarget.style.display='none'}}/>}<span className="level-name-copy"><strong>{l.name}</strong><small>{l.creators.join(', ')||'Creator not listed'} · ID {l.level_id}</small></span></Link><strong className="level-points">{l.points}</strong><span className="verifier">{l.verifier?<Link className="profile-link" to={'/player/'+encodeURIComponent(l.verifier)}>{l.verifier}</Link>:'—'}</span><ArrowRight className="row-arrow" size={16}/></div>)}</div>}
function ListPage({levels,loading,search,setSearch,configured}:{levels:Level[];loading:boolean;search:string;setSearch:(s:string)=>void;configured:boolean}){return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><Swords size={14}/> THE RANKINGS</div><h1>DEMON <span>LIST</span></h1><p>Find the level that's going to test everything you've got.</p></div><div className="list-toolbar"><div className="searchbox"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search levels, creators, or level ID..." aria-label="Search levels"/></div><span className="result-count">{configured?levels.length+' RESULTS':'AWAITING DATABASE'}</span></div><LevelTable levels={levels} loading={loading} configured={configured}/></main>}
async function enrichCompletionRows(rows:any[]):Promise<any[]>{if(!supabase||!rows.length)return rows;const playerIds=[...new Set(rows.map(r=>r.submitter_id).filter(Boolean))];const levelIds=[...new Set(rows.map(r=>r.level_id).filter(Boolean))];const [p,l]=await Promise.all([supabase.from('profiles').select('id,gd_username,points').in('id',playerIds),supabase.from('levels').select('id,name,sort_order,gd_level_id,thumbnail_url,points').in('id',levelIds)]);return rows.map(r=>({...r,player:(p.data||[]).find((x:any)=>x.id===r.submitter_id)||null,level:(l.data||[]).find((x:any)=>x.id===r.level_id)||null}))}
function LevelPage({levels,session,onLogin,setNotice}:{levels:Level[];session:Session|null;onLogin:()=>void;setNotice:(s:string)=>void}){const id=window.location.hash.split('/').pop()||'';const l=levels.find(x=>x.id===id);const [records,setRecords]=useState<any[]>([]),[recordsLoading,setRecordsLoading]=useState(true);useEffect(()=>{let alive=true;if(!supabase||!id){setRecords([]);setRecordsLoading(false);return}setRecordsLoading(true);supabase.rpc('wcl_public_accepted_records',{p_level_id:id,p_submitter_id:null,p_limit:100}).then(({data})=>{if(alive){setRecords((data||[]).map((r:any)=>({...r,player:{gd_username:r.gd_username},level:{name:r.level_name,thumbnail_url:r.level_thumbnail_url,points:r.level_points}})));setRecordsLoading(false)}});return()=>{alive=false}},[id]);if(!l)return <main className="page wrap"><div className="empty-state page-empty"><div className="empty-icon"><Search/></div><h3>LEVEL NOT FOUND</h3><p>This level may not be ranked yet, or the database hasn't been connected.</p><Link className="button button-primary" to="/list">Back to demon list</Link></div></main>;return <main className="page wrap"><Link to="/list" className="back-link">← Back to demon list</Link><div className="detail-card"><div className="detail-rank">RANK <strong>#{l.rank}</strong></div><div className="eyebrow">TGH RANKED LEVEL</div><h1>{l.name}</h1><p className="detail-sub">By {l.creators.join(', ')||'Creator not listed'} · Level ID {l.level_id}</p>{l.thumbnail_url&&<img className="detail-thumbnail" src={l.thumbnail_url} alt={l.name+' level thumbnail'}/>}<div className="detail-facts"><div><small>MIN. RECORD</small><strong>{l.minimum_record_percent}%</strong></div><div><small>VERIFIER</small><strong>{l.verifier?<Link className="profile-link" to={'/player/'+encodeURIComponent(l.verifier)}>{l.verifier}</Link>:'Not listed'}</strong></div><div><small>LEVEL POINTS</small><strong>{l.points}</strong></div></div>{l.description&&<p>{l.description}</p>}{l.video_url&&<a className="text-link" href={l.video_url} target="_blank" rel="noreferrer">Verification video <ExternalLink size={14}/></a>}<button className="button button-primary" onClick={()=>session?(window.location.hash='#/submit',setNotice('Select this level on the submission form to continue.')):onLogin()}>Submit a record <ArrowRight size={16}/></button></div><section className="level-records"><div className="section-heading"><div><h2>RECORDS</h2><p>Accepted player completions and their proof.</p></div><Link to="/submit" className="text-link">SUBMIT RECORD <ArrowRight size={14}/></Link></div>{recordsLoading?<div className="table-state"><div className="spinner"/> Loading records…</div>:records.length?<div className="level-table"><div className="table-head"><span>PROGRESS</span><span>PLAYER</span><span>POINTS</span><span>VIDEO PROOF</span><span/></div>{records.map((r:any)=><div className="level-row" key={r.id}><span className="rank">{r.progress_percent??100}%</span><span className="level-name"><span className="level-name-copy"><strong><Link className="profile-link" to={'/player/'+encodeURIComponent(r.submitter_id||r.player?.gd_username||'')}>{r.player?.gd_username||'Player'}</Link></strong><small>{r.verification_submission_id?'Level verifier':'Accepted completion'}</small></span></span><span>{r.points_awarded}</span><span>{r.proof_url?<a className="text-link" href={r.proof_url} target="_blank" rel="noreferrer">Watch <ExternalLink size={12}/></a>:'Verification proof'}</span><span/></div>)}</div>:<div className="empty-state"><h3>NO ACCEPTED RECORDS YET</h3><p>Approved completions will appear here after staff review.</p><Link className="button button-primary" to="/submit">Submit a record</Link></div>}</section></main>}
function SubmitPage({levels,session,onLogin,setNotice}:{levels:Level[];session:Session|null;onLogin:()=>void;setNotice:(s:string)=>void}){const [levelId,setLevelId]=useState(''),[video,setVideo]=useState(''),[raw,setRaw]=useState(''),[progress,setProgress]=useState('100'),[details,setDetails]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();if(!session){onLogin();return}if(!supabase){setNotice('Supabase is not configured yet.');return}if(!/^https:\/\//i.test(video)||!/^https:\/\//i.test(raw)){setNotice('Both the public completion video and raw footage must use HTTPS links.');return}const chosen=levels.find(l=>l.id===levelId);const pct=Number(progress);if(!chosen){setNotice('Choose a ranked level.');return}if(!Number.isInteger(pct)||pct<chosen.minimum_record_percent||pct>100){setNotice('This level requires at least '+chosen.minimum_record_percent+'% progress.');return}setBusy(true);const {error}=await supabase.from('completion_submissions').insert({submitter_id:session.user.id,level_id:levelId,proof_url:video.trim(),raw_footage_url:raw.trim(),progress_percent:pct,player_notes:details.trim()||null,status:'pending',points_awarded:0});setBusy(false);if(error){setNotice(error.message);return}setLevelId('');setVideo('');setRaw('');setProgress('100');setDetails('');setNotice('Record submitted for review. Points are awarded only after staff accepts the evidence.')}return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><Award size={14}/> COMPLETION EVIDENCE</div><h1>SUBMIT A <span>RECORD</span></h1><p>Submit the public completion video, unedited raw footage, and your achieved progress. Staff will review the evidence.</p></div>{!session&&<div className="inline-notice"><ShieldCheck size={19}/><span><strong>Player account required</strong><small>Log in to submit a completion and track its review status.</small></span><button className="button button-primary" onClick={onLogin}>Log in <ArrowRight size={14}/></button></div>}<form className="form-card" onSubmit={submit}><label>RANKED LEVEL<select required value={levelId} onChange={e=>{setLevelId(e.target.value);const l=levels.find(x=>x.id===e.target.value);if(l)setProgress(String(l.minimum_record_percent))}}><option value="">Choose a level...</option>{levels.map(l=><option key={l.id} value={l.id}>#{l.rank} — {l.name} (ID {l.level_id}) · minimum {l.minimum_record_percent}%</option>)}</select></label><label>COMPLETION VIDEO URL<input required type="url" value={video} onChange={e=>setVideo(e.target.value)} placeholder="Public YouTube video URL"/></label><label>RAW FOOTAGE URL<input required type="url" value={raw} onChange={e=>setRaw(e.target.value)} placeholder="Shareable link to unedited raw footage"/></label><label>PROGRESS (%)<input required type="number" min={levels.find(l=>l.id===levelId)?.minimum_record_percent??1} max="100" step="1" value={progress} onChange={e=>setProgress(e.target.value)}/><small className="form-hint">{levelId?'Minimum required: '+(levels.find(l=>l.id===levelId)?.minimum_record_percent??100)+'%':'Select a level to see its progress requirement.'}</small></label><label>ADDITIONAL DETAILS <span className="optional">OPTIONAL</span><textarea value={details} onChange={e=>setDetails(e.target.value)} rows={4} maxLength={1000} placeholder="Anything the reviewers should know about this run..."/></label><div className="form-foot"><span><ShieldCheck size={15}/> Points are calculated from level points and progress.</span><button className="button button-primary" type="submit" disabled={busy}>{busy?'Submitting...':'Submit for review'} <ArrowRight size={16}/></button></div>{!supabaseConfigured&&<p className="form-hint">Database setup is required before submissions can be saved.</p>}</form></main>}
function youtubeThumbnail(url:string){try{const u=new URL(url);let id='';if(u.hostname==='youtu.be')id=u.pathname.slice(1);else if(u.hostname.endsWith('youtube.com'))id=u.searchParams.get('v')||u.pathname.match(/\/(?:embed|shorts|live)\/([^/?]+)/)?.[1]||'';return id?'https://img.youtube.com/vi/'+id+'/hqdefault.jpg':''}catch{return ''}}
function SubmitLevelPage({session,onLogin,setNotice}:{session:Session|null;onLogin:()=>void;setNotice:(s:string)=>void}){
 const [name,setName]=useState(''),[gameId,setGameId]=useState(''),[creators,setCreators]=useState(''),[verifier,setVerifier]=useState(''),[video,setVideo]=useState(''),[thumbnail,setThumbnail]=useState(''),[description,setDescription]=useState(''),[length,setLength]=useState('Unrated'),[suggestedPoints,setSuggestedPoints]=useState('10'),[minimumProgress,setMinimumProgress]=useState('100'),[busy,setBusy]=useState(false);
 async function submit(e:FormEvent){e.preventDefault();if(!session){onLogin();return}if(!supabase){setNotice('Supabase is not configured yet.');return}const id=gameId.trim();if(!/^[0-9]{1,20}$/.test(id)){setNotice('Enter the numeric Geometry Dash level ID.');return}const videoUrl=video.trim();if(!/^https:\/\/(www\.)?(youtube\.com|youtu\.be)\//i.test(videoUrl)){setNotice('Use a YouTube verification video URL.');return}const thumb=thumbnail.trim()||youtubeThumbnail(videoUrl);if(!thumb){setNotice('Add a thumbnail image URL, or use a YouTube verification video.');return}if(!/^https:\/\//i.test(thumb)){setNotice('Use an HTTPS thumbnail URL.');return}if(description.trim().length>2000){setNotice('Description must be 2,000 characters or fewer.');return}setBusy(true);const {data:verifierProfile,error:lookupError}=await supabase.from('profiles').select('id,gd_username').ilike('gd_username',verifier.trim()).maybeSingle();if(lookupError||!verifierProfile){setBusy(false);setNotice('The verifier must have a registered TGH account. Check the exact username and try again.');return}const {error}=await supabase.from('level_submissions').insert({submitter_id:session.user.id,name:name.trim(),gd_level_id:id,creator:creators.trim(),description:description.trim(),suggested_points:Number(suggestedPoints),length,youtube_url:videoUrl,thumbnail_url:thumb,minimum_record_percent:Number(minimumProgress),verified_by:verifierProfile.id,status:'pending'});setBusy(false);if(error){setNotice(error.message);return}setName('');setGameId('');setCreators('');setVerifier('');setVideo('');setThumbnail('');setDescription('');setSuggestedPoints('10');setMinimumProgress('100');setNotice('Level submitted for review. Staff will confirm placement and award the verifier’s points if approved.')}
 return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><ShieldCheck size={14}/> LEVEL VERIFICATION</div><h1>SUBMIT A <span>LEVEL</span></h1><p>Submit the level ID, verification video, description, creator, thumbnail, and verifier. Staff review the proposal before it appears on the list.</p></div>{!session&&<div className="inline-notice"><UserRound size={19}/><span><strong>Player account required</strong><small>Sign in to propose a level and track the review.</small></span><button className="button button-primary" onClick={onLogin}>Log in <ArrowRight size={14}/></button></div>}<form className="form-card" onSubmit={submit}>
 <label>LEVEL NAME<input required maxLength={100} value={name} onChange={e=>setName(e.target.value)} placeholder="Level name"/></label>
 <label>GEOMETRY DASH LEVEL ID<input required inputMode="numeric" pattern="[0-9]{1,20}" value={gameId} onChange={e=>setGameId(e.target.value)} placeholder="Numeric level ID"/></label>
 <label>CREATOR(S)<input required maxLength={80} value={creators} onChange={e=>setCreators(e.target.value)} placeholder="Creator name(s)"/></label>
 <label>VERIFIER TGH USERNAME<input required maxLength={32} value={verifier} onChange={e=>setVerifier(e.target.value)} placeholder="Registered username of the verifier"/><small className="form-hint">The verifier must already have a TGH profile so verification points go to the right player.</small></label>
 <label>VERIFICATION VIDEO URL<input required type="url" value={video} onChange={e=>setVideo(e.target.value)} placeholder="https://youtube.com/watch?v=..."/></label>
 <label>LEVEL THUMBNAIL URL <span className="optional">OPTIONAL FOR YOUTUBE LINKS</span><input type="url" value={thumbnail} onChange={e=>setThumbnail(e.target.value)} placeholder="Leave blank to use the YouTube video thumbnail"/></label>
 <label>DESCRIPTION<textarea required maxLength={2000} rows={5} value={description} onChange={e=>setDescription(e.target.value)} placeholder="Describe the level and relevant verification details..."/></label>

 <label>LEVEL LENGTH<select value={length} onChange={e=>setLength(e.target.value)}><option>Unrated</option><option>Short</option><option>Medium</option><option>Long</option><option>XL</option></select></label>
 <label>SUGGESTED POINTS<input required type="number" min="0" max="1000000" value={suggestedPoints} onChange={e=>setSuggestedPoints(e.target.value)}/><small className="form-hint">A moderator sets the final score when approving the level.</small></label>
 <label>MINIMUM RECORD PROGRESS (%)<input required type="number" min="1" max="100" value={minimumProgress} onChange={e=>setMinimumProgress(e.target.value)}/></label>
 <div className="form-foot"><span><ShieldCheck size={15}/> Approved levels appear on the list with this thumbnail.</span><button className="button button-primary" type="submit" disabled={busy}>{busy?'Submitting...':'Submit level for review'} <ArrowRight size={16}/></button></div>
 </form></main>
}
function PlayersPage({configured}:{configured:boolean}){const [players,setPlayers]=useState<any[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState('');useEffect(()=>{let alive=true;async function load(){if(!supabase||!configured){setLoading(false);return}const {data,error}=await supabase.rpc('wcl_public_player_points');if(!alive)return;if(error){setError(error.message);setLoading(false);return}setPlayers(data||[]);setLoading(false)}load();return()=>{alive=false}},[configured]);return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><Trophy size={14}/> COMMUNITY RANKINGS</div><h1>PLAYER <span>POINTS</span></h1><p>Points are awarded by the database when staff accepts a completion or verifies a level. Level scores determine the award; eligible partial completions are weighted by progress.</p></div>{loading?<div className="table-state"><div className="spinner"/> Loading player points…</div>:!configured?<div className="empty-state"><h3>DATABASE NOT CONNECTED</h3><p>Connect Supabase to load player scores.</p></div>:error?<div className="empty-state"><h3>POINTS UNAVAILABLE</h3><p>{error}</p></div>:!players.length?<div className="empty-state"><h3>THE SCOREBOARD IS QUIET</h3><p>Accepted completions and verified levels will appear here.</p></div>:<div className="level-table points-table"><div className="table-head"><span>RANK</span><span>PLAYER</span><span>TOTAL PTS</span><span>COMPLETION PTS</span><span>VERIFICATION PTS</span><span>COMPLETIONS / VERIFIED</span></div>{players.map((p,i)=><div className="level-row" key={p.player_id}><span className="rank">#{i+1}</span><span className="level-name"><span className="level-name-copy"><strong><Link className="profile-link" to={'/player/'+encodeURIComponent(p.gd_username)}>{p.gd_username}</Link></strong><small>{p.completions} accepted completions · {p.verifications} verified levels</small></span></span><strong className="points-total">{p.points}</strong><span>{p.completion_points}</span><span>{p.verification_points}</span><span>{p.completions} / {p.verifications}</span></div>)}</div>}</main>}
function StaffPage({session,isStaff,setNotice,onLogin}:{session:Session|null;isStaff:boolean;setNotice:(s:string)=>void;onLogin:()=>void}){const [levelSubs,setLevelSubs]=useState<any[]>([]),[recordSubs,setRecordSubs]=useState<any[]>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState('');async function load(){if(!supabase||!session||!isStaff){setLoading(false);return}setLoading(true);const [ls,rs]=await Promise.all([supabase.from('level_submissions').select('*').in('status',['pending','needs_evidence']).order('created_at'),supabase.from('completion_submissions').select('*').in('status',['pending','needs_evidence']).order('created_at')]);if(ls.error||rs.error){setNotice(ls.error?.message||rs.error?.message||'Could not load the review queue.');setLoading(false);return}const proposals=ls.data||[];const submitterIds=[...new Set(proposals.flatMap((x:any)=>[x.submitter_id,x.verified_by]).filter(Boolean))];let profiles:any[]=[];if(submitterIds.length){const {data}=await supabase.from('profiles').select('id,gd_username').in('id',submitterIds);profiles=data||[]}setLevelSubs(proposals.map((x:any)=>({...x,submitter:profiles.find((p:any)=>p.id===x.submitter_id)||null,verifier:profiles.find((p:any)=>p.id===x.verified_by)||null})));setRecordSubs(await enrichCompletionRows(rs.data||[]));setLoading(false)}useEffect(()=>{load()},[session,isStaff]);async function reviewLevel(id:string,status:'approved'|'rejected'|'needs_evidence'){if(!supabase||!session)return;const item=levelSubs.find(x=>x.id===id);if(!item)return;let note:string|null=null;let points=Number(item.suggested_points)||0;if(status==='approved'){const entered=window.prompt('Final points for this level:',String(points));if(entered===null)return;points=Number(entered);if(!Number.isInteger(points)||points<0||points>1000000){setNotice('Points must be a whole number between 0 and 1,000,000.');return}}else{const entered=window.prompt(status==='rejected'?'Reason for rejection?':'What additional evidence is needed?');if(entered===null)return;note=entered.trim()||null}setBusy(id);const {error}=await supabase.rpc('wcl_review_level_submission',{p_submission_id:id,p_status:status,p_points:points,p_note:note});setBusy('');if(error)setNotice(error.message);else{setNotice(status==='approved'?'Level approved and published; verifier points awarded automatically.':'Level submission review updated.');await load()}}async function reviewRecord(id:string,status:'approved'|'rejected'|'needs_evidence'){if(!supabase||!session)return;let note:string|null=null;if(status!=='approved'){const entered=window.prompt(status==='rejected'?'Reason for rejection?':'What additional evidence is needed?');if(entered===null)return;note=entered.trim()||null}setBusy(id);const {error}=await supabase.from('completion_submissions').update({status,reviewer_id:session.user.id,review_note:note,reviewed_at:new Date().toISOString()}).eq('id',id);setBusy('');if(error)setNotice(error.message);else{setNotice(status==='approved'?'Completion accepted and points awarded automatically.':'Completion review updated.');await load()}}if(!session)return <main className="page wrap"><div className="empty-state page-empty"><h3>STAFF SIGN-IN REQUIRED</h3><p>Sign in with a moderator or administrator account.</p><button className="button button-primary" onClick={onLogin}>Log in</button></div></main>;if(!isStaff)return <main className="page wrap"><div className="empty-state page-empty"><h3>STAFF ACCESS ONLY</h3><p>Your account does not have moderation permissions.</p></div></main>;return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><ShieldCheck size={14}/> MODERATION</div><h1>STAFF <span>REVIEW</span></h1><p>Review level verification proposals and completion evidence. The existing Supabase review functions award points and record audit events.</p></div>{loading?<div className="table-state"><div className="spinner"/> Loading review queue…</div>:<><h2 className="subheading">LEVEL SUBMISSIONS ({levelSubs.length})</h2>{levelSubs.length?levelSubs.map(s=><article className="review-card" key={s.id}>{s.thumbnail_url&&<img className="review-thumb" src={s.thumbnail_url} alt="Submitted level thumbnail"/>}<div className="review-body"><h3>{s.name} <small>· ID {s.gd_level_id||'not supplied'}</small></h3><p>Creator: {s.creator} · Verifier: {s.verifier?<Link className="profile-link" to={'/player/'+encodeURIComponent(s.verifier.id)}>{s.verifier.gd_username}</Link>:'Unknown'} · Submitted by {s.submitter?<Link className="profile-link" to={'/player/'+encodeURIComponent(s.submitter.id)}>{s.submitter.gd_username}</Link>:'Player'}</p><p>{s.description}</p><p>Suggested points: {s.suggested_points} · Length: {s.length} · Minimum record: {s.minimum_record_percent??100}%</p>{s.youtube_url&&<a className="text-link" href={s.youtube_url} target="_blank" rel="noreferrer">Watch verification video <ExternalLink size={13}/></a>}<div className="review-actions"><button disabled={busy===s.id} onClick={()=>reviewLevel(s.id,'approved')}>Approve / publish</button><button disabled={busy===s.id} onClick={()=>reviewLevel(s.id,'needs_evidence')}>Request evidence</button><button disabled={busy===s.id} onClick={()=>reviewLevel(s.id,'rejected')}>Reject</button></div></div></article>):<p className="quiet-copy">No level proposals waiting for review.</p>}<h2 className="subheading">COMPLETION RECORDS ({recordSubs.length})</h2>{recordSubs.length?recordSubs.map(s=><article className="review-card" key={s.id}>{s.level?.thumbnail_url&&<img className="review-thumb" src={s.level.thumbnail_url} alt="Level thumbnail"/>}<div className="review-body"><h3>{s.level?.name||'Ranked level'} <small>· {s.player?<Link className="profile-link" to={'/player/'+encodeURIComponent(s.submitter_id||s.player.id)}>{s.player.gd_username}</Link>:'Player'}</small></h3><p>Progress: {s.progress_percent??'—'}% · Points if accepted: {s.level?.points??'—'}</p>{s.player_notes&&<p>{s.player_notes}</p>}<a className="text-link" href={s.proof_url} target="_blank" rel="noreferrer">Watch completion video <ExternalLink size={13}/></a>{s.raw_footage_url&&<p><a className="text-link" href={s.raw_footage_url} target="_blank" rel="noreferrer">Open raw footage <ExternalLink size={13}/></a></p>}{s.review_note&&<p>Review note: {s.review_note}</p>}<div className="review-actions"><button disabled={busy===s.id} onClick={()=>reviewRecord(s.id,'approved')}>Accept</button><button disabled={busy===s.id} onClick={()=>reviewRecord(s.id,'needs_evidence')}>Request evidence</button><button disabled={busy===s.id} onClick={()=>reviewRecord(s.id,'rejected')}>Reject</button></div></div></article>):<p className="quiet-copy">No completion records waiting for review.</p>}</>}</main>}

function AdminPage({session,isAdmin,setNotice,onLogin}:{session:Session|null;isAdmin:boolean;setNotice:(s:string)=>void;onLogin:()=>void}){
 const [rows,setRows]=useState<any[]>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState('');
 async function load(){if(!supabase||!session||!isAdmin){setLoading(false);return}setLoading(true);const {data,error}=await supabase.from('levels').select('id,sort_order,name,gd_level_id,creator,description,points,difficulty,length,youtube_url,thumbnail_url,verifier,minimum_record_percent,status,admin_hidden').order('sort_order').limit(500);if(error)setNotice(error.message);setRows(data||[]);setLoading(false)}
 useEffect(()=>{load()},[session,isAdmin]);
 async function rankLevel(l:any){const value=window.prompt('New rank number for '+l.name, String(l.sort_order));if(value===null)return;const rank=Number(value);if(!Number.isInteger(rank)||rank<1||rank>100000){setNotice('Rank must be a whole number from 1 to 100000.');return}setBusy(l.id);const {error}=await supabase!.rpc('wcl_admin_set_level_rank',{p_level_id:l.id,p_rank:rank});setBusy('');if(error)setNotice(error.message);else{setNotice('Rank updated.');await load()}}
 async function editLevel(l:any){const name=window.prompt('Level name',l.name);if(name===null)return;const gdId=window.prompt('Geometry Dash level ID',l.gd_level_id||'');if(gdId===null)return;const creator=window.prompt('Creator',l.creator||'');if(creator===null)return;const pointsText=window.prompt('Level points',String(l.points??0));if(pointsText===null)return;const points=Number(pointsText);if(!Number.isInteger(points)||points<0||points>1000000){setNotice('Points must be a whole number from 0 to 1,000,000.');return}const minimumText=window.prompt('Minimum record percent (1–100)',String(l.minimum_record_percent??100));if(minimumText===null)return;const minimum=Number(minimumText);if(!Number.isInteger(minimum)||minimum<1||minimum>100){setNotice('Minimum record percent must be between 1 and 100.');return}const verifier=window.prompt('Verifier username (blank to clear)',l.verifier||'');if(verifier===null)return;const video=window.prompt('Verification video URL (HTTPS or blank)',l.youtube_url||'');if(video===null)return;const description=window.prompt('Description (blank to clear)',l.description||'');if(description===null)return;setBusy(l.id);const {error}=await supabase!.rpc('wcl_admin_update_level',{p_level_id:l.id,p_name:name.trim(),p_gd_level_id:gdId.trim(),p_creator:creator.trim(),p_description:description.trim(),p_points:points,p_minimum_record_percent:minimum,p_verifier:verifier.trim(),p_youtube_url:video.trim()});setBusy('');if(error)setNotice(error.message);else{setNotice('Level details saved.');await load()}}
 async function removeLevel(l:any){if(!window.confirm('Remove "'+l.name+'" from the public Demonlist? Existing records and proof are preserved. You can restore it from the admin panel.'))return;setBusy(l.id);const {error}=await supabase!.rpc('wcl_admin_set_level_visibility',{p_level_id:l.id,p_visible:false});setBusy('');if(error)setNotice(error.message);else{setNotice('Level removed from the public list; historical records were preserved.');await load()}}
 async function restoreLevel(l:any){setBusy(l.id);const {error}=await supabase!.rpc('wcl_admin_set_level_visibility',{p_level_id:l.id,p_visible:true});setBusy('');if(error)setNotice(error.message);else{setNotice('Level restored to the public list.');await load()}}
 async function resubmitLevel(l:any){if(!window.confirm('Create a fresh pending level submission from "'+l.name+'"? The current version will be hidden until the new submission is reviewed.'))return;setBusy(l.id);const {error}=await supabase!.rpc('wcl_admin_resubmit_level',{p_level_id:l.id});setBusy('');if(error)setNotice(error.message);else setNotice('A fresh level submission was created in the staff review queue.')}
 if(!session)return <main className="page wrap"><div className="empty-state page-empty"><h3>ADMIN SIGN-IN REQUIRED</h3><p>Sign in with Solance’s administrator account.</p><button className="button button-primary" onClick={onLogin}>Log in</button></div></main>;
 if(!isAdmin)return <main className="page wrap"><div className="empty-state page-empty"><h3>ADMIN ACCESS ONLY</h3><p>This panel is restricted to administrator accounts.</p></div></main>;
 return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><ShieldCheck size={14}/> OWNER CONTROLS</div><h1>ADMIN <span>PANEL</span></h1><p>Full Demonlist controls: reorder ranks, edit level metadata and points, remove or restore levels, and create fresh submissions for review.</p></div><div className="inline-notice"><ShieldCheck size={18}/><span><strong>Administrator access</strong><small>Changes are permission-checked by Supabase. Removing a level hides it from the public list without deleting historical player records.</small></span></div>{loading?<div className="table-state"><div className="spinner"/> Loading all levels…</div>:<div className="admin-level-list"><div className="section-heading"><div><h2>LEVEL MANAGEMENT</h2><p>{rows.filter(x=>x.status==='published'&&!x.admin_hidden).length} published · {rows.filter(x=>x.admin_hidden).length} hidden</p></div><button className="button button-secondary" onClick={load}>Refresh</button></div>{rows.map(l=><article className="review-card admin-level-card" key={l.id}><div className="review-body"><h3>#{l.sort_order} · {l.name} <small>· GD ID {l.gd_level_id||'—'}</small></h3><p>Creator: {l.creator||'—'} · Points: {l.points??0} · Minimum record: {l.minimum_record_percent??100}% · Status: {l.admin_hidden?'hidden':l.status}</p><p>Verifier: {l.verifier||'—'} · Length: {l.length||'—'}</p><div className="review-actions"><button disabled={busy===l.id} onClick={()=>rankLevel(l)}>Change rank</button><button disabled={busy===l.id} onClick={()=>editLevel(l)}>Edit level</button><button disabled={busy===l.id} onClick={()=>resubmitLevel(l)}>Re-submit for review</button>{l.admin_hidden?<button disabled={busy===l.id} onClick={()=>restoreLevel(l)}>Restore level</button>:<button disabled={busy===l.id} onClick={()=>removeLevel(l)}>Remove from list</button>}</div></div></article>)}</div>}<UnverifiedAdminPanel session={session} isAdmin={isAdmin} setNotice={setNotice}/></main>
}


function UnverifiedListPage({configured,session,onLogin,setNotice}:{configured:boolean;session:Session|null;onLogin:()=>void;setNotice:(s:string)=>void}){
 const [rows,setRows]=useState<any[]>([]),[loading,setLoading]=useState(true),[search,setSearch]=useState('');
 useEffect(()=>{let alive=true;async function load(){if(!supabase||!configured){setLoading(false);return}setLoading(true);const {data,error}=await supabase.from('unverified_levels').select('id,name,gd_level_id,creator,progress_percent,evidence_url,notes,submitter_id,created_at').order('progress_percent',{ascending:false}).order('created_at',{ascending:false}).limit(300);if(!alive)return;if(error){setNotice(error.message);setRows([]);setLoading(false);return}const ids=[...new Set((data||[]).map((x:any)=>x.submitter_id).filter(Boolean))];const profiles=ids.length?await supabase.from('profiles').select('id,gd_username').in('id',ids):{data:[] as any[]};setRows((data||[]).map((x:any)=>({...x,player:(profiles.data||[]).find((p:any)=>p.id===x.submitter_id)?.gd_username||'Player'})));setLoading(false)}load();return()=>{alive=false}},[configured,setNotice]);
 const filtered=rows.filter(x=>[x.name,x.gd_level_id||'',x.creator,x.player,x.notes||''].join(' ').toLowerCase().includes(search.toLowerCase()));
 return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><Zap size={14}/> PROGRESS TRACKING · NO POINTS</div><h1>UNVERIFIED <span>LIST</span></h1><p>For brutally hard levels that are not verified yet. Submit your best progress of 21% or higher with evidence. No verifier is required, and this list never awards points.</p><div className="unverified-rules"><span><strong>21%+</strong> progress required</span><span><strong>Evidence</strong> link required</span><span><strong>0</strong> points awarded</span></div></div><div className="list-toolbar"><div className="searchbox"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search level, creator, player, or ID…" aria-label="Search unverified levels"/></div><Link to="/submit-unverified" className="filter-button">Submit a level + run →</Link></div>{!session&&<div className="inline-notice"><UserRound size={18}/><span><strong>Want to add your progress?</strong><small>Sign in to submit a level and evidence. Verification is not required.</small></span><button className="button button-primary" onClick={onLogin}>Log in <ArrowRight size={14}/></button></div>}{loading?<div className="table-state"><div className="spinner"/> Loading unverified levels…</div>:!configured?<div className="empty-state"><h3>UNVERIFIED LIST NOT CONNECTED</h3><p>Connect the database to view submissions.</p></div>:!filtered.length?<div className="empty-state"><div className="empty-icon"><Zap size={23}/></div><h3>NO UNVERIFIED LEVELS YET</h3><p>Got 21% or more on an insanely hard unverified level? Be the first to post your progress with evidence.</p><Link to="/submit-unverified" className="button button-primary">Submit your progress <ArrowRight size={15}/></Link></div>:<div className="unverified-list">{filtered.map((x:any,i:number)=><article className="unverified-card" key={x.id}><div className="unverified-place">#{String(i+1).padStart(2,'0')}</div><div className="unverified-main"><h3>{x.name}</h3><p>By {x.creator} {x.gd_level_id?'· GD ID '+x.gd_level_id:''}</p><small>Submitted by <Link className="profile-link" to={'/player/'+encodeURIComponent(x.player)}>{x.player}</Link> · {new Date(x.created_at).toLocaleDateString()}</small>{x.notes&&<p className="unverified-notes">{x.notes}</p>}</div><div className="unverified-score"><strong>{x.progress_percent}%</strong><span>BEST PROGRESS</span><a href={x.evidence_url} target="_blank" rel="noreferrer" className="text-link">View evidence <ExternalLink size={13}/></a></div></article>)}</div>}<p className="unverified-footnote">This is a community progress board, not a verified ranking. Runs are not verified by TGH staff and do not earn points.</p></main>
}
function SubmitUnverifiedPage({session,onLogin,setNotice}:{session:Session|null;onLogin:()=>void;setNotice:(s:string)=>void}){
 const [name,setName]=useState(''),[gameId,setGameId]=useState(''),[creator,setCreator]=useState(''),[progress,setProgress]=useState('21'),[evidence,setEvidence]=useState(''),[notes,setNotes]=useState(''),[busy,setBusy]=useState(false);
 async function submit(e:FormEvent){e.preventDefault();if(!session){onLogin();return}if(!supabase){setNotice('Supabase is not configured yet.');return}const pct=Number(progress);if(!Number.isInteger(pct)||pct<21||pct>100){setNotice('Your best progress must be between 21% and 100%.');return}if(!/^https:\/\//i.test(evidence.trim())){setNotice('Evidence must be a public HTTPS link to your run.');return}if(!/^[0-9]{1,20}$/.test(gameId.trim())&&gameId.trim()!==''){setNotice('The Geometry Dash level ID must be numeric, or leave it blank.');return}setBusy(true);const {error}=await supabase.from('unverified_levels').insert({name:name.trim(),gd_level_id:gameId.trim()||null,creator:creator.trim(),progress_percent:pct,evidence_url:evidence.trim(),notes:notes.trim(),submitter_id:session.user.id});setBusy(false);if(error){setNotice(error.message);return}setName('');setGameId('');setCreator('');setProgress('21');setEvidence('');setNotes('');setNotice('Added to the Unverified List. No verification or points are required.');window.location.hash='#/unverified'}
 return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><Zap size={14}/> UNVERIFIED PROGRESS</div><h1>SUBMIT TO THE <span>UNVERIFIED LIST</span></h1><p>Post an extremely hard unverified level and your best progress. You do not need to verify the level — just provide evidence of a run over 20%.</p></div>{!session&&<div className="inline-notice"><UserRound size={18}/><span><strong>Player account required</strong><small>Sign in to attach your run to your profile.</small></span><button className="button button-primary" onClick={onLogin}>Log in <ArrowRight size={14}/></button></div>}<form className="form-card" onSubmit={submit}><label>LEVEL NAME<input required maxLength={160} value={name} onChange={e=>setName(e.target.value)} placeholder="Name of the unverified level"/></label><label>GEOMETRY DASH LEVEL ID <span className="optional">OPTIONAL</span><input inputMode="numeric" pattern="[0-9]{0,20}" value={gameId} onChange={e=>setGameId(e.target.value)} placeholder="Numeric level ID, if known"/></label><label>CREATOR<input required maxLength={120} value={creator} onChange={e=>setCreator(e.target.value)} placeholder="Level creator"/></label><label>YOUR BEST PROGRESS (%)<input required type="number" min="21" max="100" step="1" value={progress} onChange={e=>setProgress(e.target.value)}/><small className="form-hint">Minimum is 21%. This is a progress board only — no points are awarded.</small></label><label>RUN EVIDENCE URL<input required type="url" value={evidence} onChange={e=>setEvidence(e.target.value)} placeholder="Public YouTube video or other HTTPS evidence link"/><small className="form-hint">Use a link people can open to see your run. No verification video or verifier account is needed.</small></label><label>NOTES <span className="optional">OPTIONAL</span><textarea maxLength={1000} rows={4} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Any useful context about the run or level…"/></label><div className="form-foot"><span><Zap size={15}/> No verification. No points. Just progress.</span><button className="button button-primary" type="submit" disabled={busy}>{busy?'Submitting…':'Add to Unverified List'} <ArrowRight size={16}/></button></div></form></main>
}

function RecordsPage({configured}:{configured:boolean}){const [records,setRecords]=useState<any[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState('');useEffect(()=>{let alive=true;async function load(){if(!supabase||!configured){setLoading(false);return}const {data,error}=await supabase.rpc('wcl_public_accepted_records',{p_level_id:null,p_submitter_id:null,p_limit:100});if(!alive)return;if(error){setError(error.message);setLoading(false);return}setRecords((data||[]).map((r:any)=>({...r,player:{gd_username:r.gd_username},level:{name:r.level_name,thumbnail_url:r.level_thumbnail_url,points:r.level_points}})));setLoading(false)}load();return()=>{alive=false}},[configured]);return <main className="page wrap"><div className="page-hero"><div className="eyebrow"><Trophy size={14}/> VERIFIED ACHIEVEMENTS</div><h1>PLAYER <span>RECORDS</span></h1><p>Approved completions and verifications with evidence and awarded points.</p></div>{loading?<div className="table-state"><div className="spinner"/> Loading accepted records...</div>:!configured?<div className="empty-state"><h3>RECORDS NOT CONNECTED</h3><p>Connect Supabase to display accepted records.</p></div>:error?<div className="empty-state"><h3>RECORDS UNAVAILABLE</h3><p>{error}</p></div>:!records.length?<div className="empty-state"><div className="empty-icon"><Trophy/></div><h3>THE RECORD BOARD IS QUIET</h3><p>No accepted records yet. Be the first to submit a run.</p><Link className="button button-primary" to="/submit">Submit a record <ArrowRight size={15}/></Link></div>:<div className="record-list">{records.map(r=><div className="record-row" key={r.id}>{r.level?.thumbnail_url&&<img className="record-thumb" src={r.level.thumbnail_url} alt="Level thumbnail"/>}<span className="record-medal"><Award/></span><div><strong><Link className="profile-link" to={'/player/'+encodeURIComponent(r.submitter_id||r.player?.gd_username||'')}>{r.player?.gd_username||'Player'}</Link></strong><small>{r.level?.name||'Ranked level'} · {r.verification_submission_id?'Level verification':'Progress '+(r.progress_percent??100)+'%'} · {r.points_awarded} pts</small></div>{r.proof_url?<a href={r.proof_url} target="_blank" rel="noreferrer" className="text-link">Watch proof <ExternalLink size={13}/></a>:<span className="status-label">Verification</span>}</div>)}</div>}</main>}

function PlayerPage({configured}:{configured:boolean}){const identifier=decodeURIComponent(window.location.hash.split('/').pop()||'');const [profile,setProfile]=useState<any>(null),[records,setRecords]=useState<any[]>([]),[score,setScore]=useState<any>(null),[loading,setLoading]=useState(true),[error,setError]=useState('');useEffect(()=>{let alive=true;async function load(){if(!supabase||!configured||!identifier){setLoading(false);return}setLoading(true);setError('');const looksLikeId=/^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(identifier);const query=supabase.from('profiles').select('id,gd_username,points,avatar_url,banner_url,bio,theme');const result=looksLikeId?await query.eq('id',identifier).maybeSingle():await query.ilike('gd_username',identifier).maybeSingle();if(!alive)return;if(result.error){setError('Could not load this player profile.');setLoading(false);return}if(!result.data){setProfile(null);setLoading(false);return}const player=result.data;setProfile(player);const [accepted,points]=await Promise.all([supabase.rpc('wcl_public_accepted_records',{p_level_id:null,p_submitter_id:player.id,p_limit:100}),supabase.rpc('wcl_public_player_points')]);if(!alive)return;if(accepted.error)setError('Profile loaded, but records could not be retrieved.');setRecords(accepted.data||[]);setScore((points.data||[]).find((x:any)=>x.player_id===player.id)||null);setLoading(false)}load();return()=>{alive=false}},[identifier,configured]);return <main className="page wrap"><Link to="/players" className="back-link">← Back to player points</Link>{loading?<div className="table-state"><div className="spinner"/> Loading player profile…</div>:!configured?<div className="empty-state page-empty"><h3>PROFILES NOT CONNECTED</h3><p>Player profiles will appear when the database is connected.</p></div>:!profile?<div className="empty-state page-empty"><div className="empty-icon"><UserRound/></div><h3>PLAYER NOT FOUND</h3><p>We couldn't find a public profile for that username.</p><Link className="button button-primary" to="/players">View player leaderboard</Link></div>:<><section className="public-player-banner" style={profile.banner_url?{backgroundImage:'linear-gradient(90deg,rgba(10,16,24,.82),rgba(10,16,24,.2)),url('+JSON.stringify(profile.banner_url)+')'}:{}}><div className="public-player-avatar">{profile.avatar_url?<img src={profile.avatar_url} alt="Player avatar"/>:<UserRound size={36}/>}</div><div><div className="eyebrow"><UserRound size={14}/> PLAYER PROFILE</div><h1>{profile.gd_username} <span>PROFILE</span></h1><p>{profile.bio||'Public Geometry Dash stats, accepted completions, and verified levels on The GD Hub.'}</p></div></section>{error&&<div className="inline-notice"><span>{error}</span></div>}<div className="profile-score"><span><small>TOTAL POINTS</small><strong>{profile.points??0}</strong></span><span><small>ACCEPTED COMPLETIONS</small><strong>{score?.completions??0}</strong></span><span><small>LEVEL VERIFICATIONS</small><strong>{score?.verifications??0}</strong></span><span><small>COMPLETION POINTS</small><strong>{score?.completion_points??0}</strong></span><span><small>VERIFICATION POINTS</small><strong>{score?.verification_points??0}</strong></span></div><h2 className="subheading">ACCEPTED RECORDS</h2>{records.length?<div className="record-list">{records.map((r:any)=><div className="record-row" key={r.id}>{r.level_thumbnail_url&&<img className="record-thumb" src={r.level_thumbnail_url} alt="Level thumbnail"/>}<div><strong><Link className="profile-level-link" to={'/level/'+r.level_id}>{r.level_name}</Link></strong><small>{r.progress_percent??100}% · {r.points_awarded} pts · {r.verification_submission_id?'Level verification':'Completion'}</small></div>{r.proof_url?<a href={r.proof_url} target="_blank" rel="noreferrer" className="text-link">Watch proof <ExternalLink size={13}/></a>:<span className="status-label">Verification</span>}</div>)}</div>:<div className="empty-state"><p>No accepted records to display yet.</p></div>}</>}</main>}

function InfoPage({title,kicker,icon,intro,items}:{title:string;kicker:string;icon:ReactNode;intro:string;items:[string,string][]}){const words=title.split(' ');return <main className="page wrap"><div className="page-hero"><div className="eyebrow">{icon} {kicker}</div><h1>{words.slice(0,-1).join(' ')} <span>{words[words.length-1]}</span></h1><p>{intro}</p></div><div className="info-grid">{items.map(([h,b],i)=><article className="info-card" key={h}><span className="info-number">{String(i+1).padStart(2,'0')}</span><h3>{h}</h3><p>{b}</p></article>)}</div><div className="policy-note"><Clock3 size={16}/><span>Some policies are provisional and will be updated by TGH's owner. Placeholder policy should not be treated as finalized.</span></div></main>}
function ProfilePage({session,setProfileName,setNotice,onLogin}:{session:Session|null;setProfileName:(s:string)=>void;setNotice:(s:string)=>void;onLogin:()=>void}){
 const [profile,setProfile]=useState<any>(null),[records,setRecords]=useState<any[]>([]),[levelSubs,setLevelSubs]=useState<any[]>([]),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[name,setName]=useState(''),[avatar,setAvatar]=useState(''),[banner,setBanner]=useState(''),[bio,setBio]=useState(''),[theme,setTheme]=useState('dark'),[password,setPassword]=useState(''),[confirm,setConfirm]=useState('');
 function applyTheme(t:string){if(t==='dark'||t==='light')document.documentElement.dataset.theme=t;else document.documentElement.removeAttribute('data-theme');window.localStorage.setItem('tgh-theme',t)}
 useEffect(()=>{let alive=true;async function load(){if(!session||!supabase){setLoading(false);return}const [p,r,l]=await Promise.all([supabase.from('profiles').select('id,gd_username,points,avatar_url,banner_url,bio,theme,created_at').eq('id',session.user.id).maybeSingle(),supabase.from('completion_submissions').select('*').eq('submitter_id',session.user.id).order('created_at',{ascending:false}).limit(50),supabase.from('level_submissions').select('id,name,gd_level_id,status,review_note,created_at').eq('submitter_id',session.user.id).order('created_at',{ascending:false}).limit(50)]);if(!alive)return;if(p.data){setProfile(p.data);setName(p.data.gd_username||'');setProfileName(p.data.gd_username||'');setAvatar(p.data.avatar_url||'');setBanner(p.data.banner_url||'');setBio(p.data.bio||'');setTheme(p.data.theme||'dark');applyTheme(p.data.theme||'dark')}setRecords(await enrichCompletionRows(r.data||[]));setLevelSubs(l.data||[]);setLoading(false);if(p.error||r.error||l.error)setNotice(p.error?.message||r.error?.message||l.error?.message||'Unable to load profile')}void load();return()=>{alive=false}},[session,setProfileName]);
 async function upload(kind:'avatar'|'banner',file?:File){if(!file||!session||!supabase)return;if(!file.type.startsWith('image/')||file.size>5242880){setNotice('Choose a supported image no larger than 5 MB.');return}const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path=session.user.id+'/'+kind+'-'+Date.now()+'.'+ext;setSaving(true);const {error}=await supabase.storage.from('profile-assets').upload(path,file,{contentType:file.type});if(error){setSaving(false);setNotice(error.message);return}const {data}=supabase.storage.from('profile-assets').getPublicUrl(path);if(kind==='avatar')setAvatar(data.publicUrl);else setBanner(data.publicUrl);setSaving(false);setNotice('Image uploaded. Save your profile settings to publish it.')}
 async function save(){if(!supabase||!session)return;const n=name.trim();if(n.length<2||n.length>32){setNotice('Display name must be 2–32 characters.');return}if(bio.length>240){setNotice('Bio must be 240 characters or fewer.');return}if((avatar&&!/^https:\/\//i.test(avatar))||(banner&&!/^https:\/\//i.test(banner))){setNotice('Image URLs must start with https://');return}setSaving(true);const {error}=await supabase.from('profiles').update({gd_username:n,avatar_url:avatar.trim()||null,banner_url:banner.trim()||null,bio:bio.trim(),theme}).eq('id',session.user.id);setSaving(false);if(error){setNotice(error.message);return}setProfile((p:any)=>({...p,gd_username:n,avatar_url:avatar,banner_url:banner,bio,theme}));setProfileName(n);applyTheme(theme);setNotice('Profile settings saved.')}
 async function updatePassword(){if(!supabase)return;if(password.length<8||password!==confirm){setNotice(password.length<8?'Password must be at least 8 characters.':'Passwords do not match.');return}setSaving(true);const {error}=await supabase.auth.updateUser({password});setSaving(false);if(error)setNotice(error.message);else{setPassword('');setConfirm('');setNotice('Password updated.')}}
 if(!session)return <main className="page wrap"><div className="empty-state page-empty"><div className="empty-icon"><UserRound/></div><h3>YOUR ACCOUNT HQ</h3><p>Log in to edit your profile and manage account settings.</p><button className="button button-primary" onClick={onLogin}>Log in / Sign up <ArrowRight size={15}/></button></div></main>;
 return <main className="page wrap profile-settings-page"><div className="page-hero"><div className="eyebrow"><Settings2 size={14}/> ACCOUNT CONTROL CENTER</div><h1>PROFILE <span>SETTINGS</span></h1><p>Customize your player identity, appearance, and account security.</p></div>{loading?<div className="table-state"><div className="spinner"/> Loading profile…</div>:<><section className="settings-profile-card"><div className="settings-banner" style={banner?{backgroundImage:'linear-gradient(90deg,rgba(10,16,24,.78),rgba(10,16,24,.18)),url("'+banner.replace(/"/g,'%22')+'")'}:{}}><div className="settings-avatar">{avatar?<img src={avatar} alt="Profile avatar"/>:<UserRound size={34}/>}</div><div className="settings-banner-copy"><strong>{name||'Your player name'}</strong><span>{session.user.email}</span></div></div><div className="settings-profile-meta"><span><strong>{profile?.points??0}</strong><small>PLAYER POINTS</small></span><span><strong>{profile?.created_at?new Date(profile.created_at).toLocaleDateString():'—'}</strong><small>MEMBER SINCE</small></span><span><strong>{records.length}</strong><small>RECORD SUBMISSIONS</small></span></div></section>
 <section className="settings-panel"><div className="settings-panel-title"><UserRound size={18}/><div><h2>PUBLIC PROFILE</h2><p>Identity shown on your public player page.</p></div></div><div className="settings-grid"><label className="settings-field"><span>Display name</span><input value={name} onChange={e=>setName(e.target.value)} maxLength={32} placeholder="Geometry Dash name"/></label><label className="settings-field"><span>Bio <small>{bio.length}/240</small></span><textarea value={bio} onChange={e=>setBio(e.target.value)} maxLength={240} rows={3} placeholder="Tell the community about yourself…"/></label><label className="settings-field"><span>Profile picture URL</span><input value={avatar} onChange={e=>setAvatar(e.target.value)} placeholder="https://…"/></label><label className="settings-field"><span>Banner image URL</span><input value={banner} onChange={e=>setBanner(e.target.value)} placeholder="https://…"/></label><label className="settings-field"><span>Upload profile picture</span><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>void upload('avatar',e.currentTarget.files?.[0])}/><small>PNG, JPG, WebP or GIF · max 5 MB</small></label><label className="settings-field"><span>Upload banner</span><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>void upload('banner',e.currentTarget.files?.[0])}/><small>PNG, JPG, WebP or GIF · max 5 MB</small></label></div><div className="settings-actions"><button className="button button-primary" disabled={saving} onClick={()=>void save()}><Save size={15}/>{saving?'Saving…':'Save profile settings'}</button></div></section>
 <section className="settings-panel"><div className="settings-panel-title"><Palette size={18}/><div><h2>APPEARANCE</h2><p>Choose your preferred site theme.</p></div></div><div className="theme-options">{[{id:'dark',title:'Dark mode',desc:'Dark background'},{id:'light',title:'Light mode',desc:'Bright interface'},{id:'system',title:'Default theme',desc:'Use site default'}].map(t=><button key={t.id} className={theme===t.id?'theme-option selected':'theme-option'} onClick={()=>{setTheme(t.id);applyTheme(t.id)}}><span className={'theme-swatch '+t.id}/><span><strong>{t.title}</strong><small>{t.desc}</small></span><span className="theme-check">{theme===t.id?'✓':''}</span></button>)}</div><div className="settings-actions"><button className="button button-primary" disabled={saving} onClick={()=>void save()}><Save size={15}/>Save appearance</button></div></section>
 <section className="settings-panel"><div className="settings-panel-title"><LockKeyhole size={18}/><div><h2>ACCOUNT SECURITY</h2><p>Signed in as {session.user.email||'your account'}.</p></div></div><div className="settings-grid"><label className="settings-field"><span>New password</span><input type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/></label><label className="settings-field"><span>Confirm new password</span><input type="password" autoComplete="new-password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="Type it again"/></label></div><div className="settings-actions"><button className="button button-quiet" disabled={saving} onClick={()=>void updatePassword()}><LockKeyhole size={15}/>Update password</button><button className="button button-quiet" onClick={()=>{void supabase?.auth.signOut();setNotice('You have been logged out.')}}><LogIn size={15}/>Log out</button></div><p className="settings-help">Email changes are not exposed here yet. Use your current email to identify this account.</p></section>
 <h2 className="subheading">YOUR COMPLETION SUBMISSIONS</h2>{records.length?records.map(r=><div className="record-row" key={r.id}>{r.level?.thumbnail_url&&<img className="record-thumb" src={r.level.thumbnail_url} alt="Level thumbnail"/>}<div><strong>{r.level?.name||'Ranked level'}</strong><small>{new Date(r.created_at).toLocaleDateString()} · {r.progress_percent??'—'}% · {r.review_note||'No review note'}</small></div><span className="status-label">{(r.status||'pending').replace('_',' ')}</span></div>):<div className="empty-state"><p>No completion submissions yet.</p><Link className="text-link" to="/submit">Submit a record <ArrowRight size={14}/></Link></div>}<h2 className="subheading">YOUR LEVEL PROPOSALS</h2>{levelSubs.length?levelSubs.map(s=><div className="record-row" key={s.id}><div><strong>{s.name}</strong><small>ID {s.gd_level_id||'—'} · {new Date(s.created_at).toLocaleDateString()} · {s.review_note||'No review note'}</small></div><span className="status-label">{(s.status||'pending').replace('_',' ')}</span></div>):<div className="empty-state"><p>No level proposals yet.</p><Link className="text-link" to="/submit-level">Submit a level <ArrowRight size={14}/></Link></div>}</>}</main>
}
function AuthModal({onClose,onNotice}:{onClose:()=>void;onNotice:(s:string)=>void}){const [mode,setMode]=useState<'login'|'signup'|'reset'>('login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[gdUsername,setGdUsername]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();if(!supabase){onNotice('Supabase is not configured yet. Follow the setup guide in the repository README.');return}if(mode==='signup'&&gdUsername.trim().length<1){onNotice('Enter your Geometry Dash username.');return}setBusy(true);let message='';if(mode==='signup'){const {data:existing}=await supabase.from('profiles').select('id').ilike('gd_username',gdUsername.trim()).maybeSingle();if(existing){setBusy(false);onNotice('That player username is already registered. Choose another.');return}const {error}=await supabase.auth.signUp({email,password,options:{data:{gd_username:gdUsername.trim()}}});message=error?.message||'Account created. Check your email to verify your address.'}else if(mode==='reset'){const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin+window.location.pathname+'#/profile'});message=error?.message||'If that account exists, a password reset link has been sent.'}else{const {error}=await supabase.auth.signInWithPassword({email,password});message=error?.message||'Welcome back.'}setBusy(false);onNotice(message);if(mode==='login'&&!message.toLowerCase().includes('invalid')&&!message.toLowerCase().includes('error'))onClose()}return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-title"><button className="modal-close" onClick={onClose} aria-label="Close"><X/></button><div className="brand-mark modal-mark"><Gamepad2 size={25}/><i/></div><div className="eyebrow">PLAYER ACCESS</div><h2 id="auth-title">{mode==='login'?'WELCOME BACK.':mode==='signup'?'JOIN THE HUB.':'RESET PASSWORD.'}</h2><p>{mode==='signup'?'Create your player account with your Geometry Dash username.':mode==='reset'?'We’ll send you a link to reset your password.':'Sign in to submit records and track your progress.'}</p><form onSubmit={submit}>{mode==='signup'&&<label>GEOMETRY DASH USERNAME<input value={gdUsername} onChange={e=>setGdUsername(e.target.value)} required maxLength={32} autoComplete="nickname" placeholder="Your GD username"/></label>}<label>EMAIL ADDRESS<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email"/></label>{mode!=='reset'&&<label>PASSWORD<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={8} autoComplete={mode==='signup'?'new-password':'current-password'}/></label>}<button className="button button-primary auth-submit" disabled={busy}>{busy?'Please wait...':mode==='login'?'Log in':mode==='signup'?'Create account':'Send reset link'} <ArrowRight size={15}/></button></form><div className="auth-switch">{mode==='login'?<><button onClick={()=>setMode('signup')}>Create an account</button><button onClick={()=>setMode('reset')}>Forgot password?</button></>:<button onClick={()=>setMode('login')}>Back to log in</button>}</div>{!supabaseConfigured&&<div className="auth-config-note">Authentication activates after Supabase environment variables are configured.</div>}</section></div>}